create type account_status as enum ('kho', 'dang_cay', 'done', 'da_giao_cho_ben_thu', 'da_nhan_tien');
create table account_milestones (id uuid primary key default gen_random_uuid(), account_id uuid not null, level integer not null, price bigint not null check (price >= 0), note text, unique(account_id, level));
create table accounts (id uuid primary key default gen_random_uuid(), username text not null, source text not null check (source in ('Bên A','Bên B','Bên C')), status account_status not null default 'kho', position integer not null default 0, current_holder text, current_level integer not null default 0, target_milestone_id uuid, amount_received bigint check (amount_received is null or amount_received > 0), completed_at timestamptz, delivered_at timestamptz, paid_at timestamptz, image_url text, image_expires_at timestamptz, version integer not null default 0, updated_at timestamptz not null default now(), constraint target_milestone_same_account foreign key (target_milestone_id) references account_milestones(id));
alter table account_milestones add constraint milestone_account_fk foreign key (account_id) references accounts(id) on delete cascade;
alter table accounts enable row level security; alter table account_milestones enable row level security;
create policy "authenticated accounts" on accounts for all to authenticated using (true) with check (true);
create policy "authenticated milestones" on account_milestones for all to authenticated using (true) with check (true);
create table holder_sessions (id uuid primary key default gen_random_uuid(), account_id uuid not null references accounts(id) on delete cascade, holder_name text not null, started_at timestamptz not null default now(), ended_at timestamptz, handed_to text, duration_seconds bigint);
alter table holder_sessions enable row level security;
create policy "authenticated sessions" on holder_sessions for all to authenticated using (true) with check (true);
create unique index holder_sessions_one_open on holder_sessions(account_id) where ended_at is null;
create or replace function touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;
create trigger accounts_updated_at before update on accounts for each row execute function touch_updated_at();
create or replace function move_account(p_account_id uuid, p_next_holder text, p_target_position integer, p_known_version integer) returns accounts language plpgsql security definer set search_path = public as $$ declare a accounts; begin select * into a from accounts where id = p_account_id for update; if a.version <> p_known_version then raise exception using errcode='P0001', message='version_conflict'; end if; if a.status not in ('kho','dang_cay') then raise exception using errcode='P0002', message='invalid_transition'; end if; if exists(select 1 from holder_sessions where account_id=a.id and ended_at is null) then update holder_sessions set ended_at=now(), handed_to=p_next_holder, duration_seconds=extract(epoch from now()-started_at)::bigint where account_id=a.id and ended_at is null; end if; if nullif(trim(p_next_holder),'') is not null then insert into holder_sessions(account_id,holder_name) values (a.id,trim(p_next_holder)); end if; update accounts set current_holder=nullif(trim(p_next_holder),''), position=p_target_position, status=case when nullif(trim(p_next_holder),'') is null then 'kho' else 'dang_cay' end, version=version+1 where id=a.id returning * into a; return a; end $$;
create or replace function transition_account(p_account_id uuid,p_action text,p_known_version integer,p_current_level integer default null,p_target_milestone_id uuid default null,p_amount_received bigint default null,p_note text default null) returns accounts language plpgsql security definer set search_path=public as $$ declare a accounts; begin select * into a from accounts where id=p_account_id for update; if a.version<>p_known_version then raise exception using errcode='P0001',message='version_conflict'; end if; if p_action='update_level' and a.status='dang_cay' then update accounts set current_level=p_current_level,version=version+1 where id=a.id returning * into a; elsif p_action='done' and a.status='dang_cay' then update holder_sessions set ended_at=now(),duration_seconds=extract(epoch from now()-started_at)::bigint where account_id=a.id and ended_at is null; update accounts set status='done',completed_at=now(),version=version+1 where id=a.id returning * into a; elsif p_action='deliver' and a.status='done' and exists(select 1 from account_milestones where id=p_target_milestone_id and account_id=a.id) then update accounts set status='da_giao_cho_ben_thu',delivered_at=now(),image_expires_at=now()+interval '3 days',target_milestone_id=p_target_milestone_id,version=version+1 where id=a.id returning * into a; elsif p_action='pay' and a.status='da_giao_cho_ben_thu' and coalesce(p_amount_received,0)>0 then update accounts set status='da_nhan_tien',paid_at=now(),amount_received=p_amount_received,version=version+1 where id=a.id returning * into a; else raise exception using errcode=case when p_action='pay' then 'P0004' else 'P0002' end,message=case when p_action='pay' then 'invalid_amount' else 'invalid_transition' end; end if; return a; end $$;
create or replace function upload_account_image(p_account_id uuid,p_path text,p_known_version integer) returns accounts language plpgsql security definer set search_path=public as $$ declare a accounts; begin select * into a from accounts where id=p_account_id for update; if a.version<>p_known_version then raise exception using errcode='P0001',message='version_conflict'; end if; update accounts set image_url=p_path,version=version+1 where id=id returning * into a; return a; end $$;
create or replace function clear_account_image(p_account_id uuid,p_known_version integer) returns accounts language plpgsql security definer set search_path=public as $$ declare a accounts; begin select * into a from accounts where id=p_account_id for update; if a.version<>p_known_version then raise exception using errcode='P0001',message='version_conflict'; end if; update accounts set image_url=null,version=version+1 where id=p_account_id returning * into a; return a; end $$;
